return $input.all().map(({json}, index) => {
  const {metrics, limits, evidence} = json;
  const {count, wins, losses, expectancyR, profitFactor, maxClosedTradeDrawdownR} = metrics ?? {};
  const {minTrades, minPayoffRatio, maxDrawdownR} = limits ?? {};
  const nonnegative = value => Number.isFinite(value) && value >= 0;
  if (![count,wins,losses].every(value => Number.isSafeInteger(value) && value >= 0) ||
      wins + losses > count || !Number.isSafeInteger(minTrades) || minTrades < 1 ||
      !Number.isFinite(minPayoffRatio) || minPayoffRatio <= 0 || !nonnegative(maxDrawdownR) ||
      !nonnegative(maxClosedTradeDrawdownR) ||
      (count > 0 && !Number.isFinite(expectancyR)) ||
      (losses > 0 && !nonnegative(profitFactor))) throw new Error("Invalid backtest metrics or quality limits");
  // Profit factor is total winning R divided by total losing R.
  const realizedPayoff = wins > 0 && losses > 0 ? profitFactor * losses / wins : null;
  const reasons = [];
  if (evidence?.ownerDecision === "REJECTED") reasons.push("OWNER_REJECTED_VERSION");
  if (count < minTrades) reasons.push("INSUFFICIENT_CLOSED_TRADES");
  if (wins <= losses) reasons.push("WINS_DO_NOT_EXCEED_LOSSES");
  if (realizedPayoff === null || realizedPayoff < minPayoffRatio) reasons.push("REALIZED_PAYOFF_NOT_PROVEN");
  if (!Number.isFinite(expectancyR) || expectancyR <= 0) reasons.push("NON_POSITIVE_NET_EXPECTANCY");
  if (maxClosedTradeDrawdownR > maxDrawdownR) reasons.push("DRAWDOWN_LIMIT_EXCEEDED");
  if (evidence?.historicalHoldout !== true || evidence?.costsApplied !== true) reasons.push("MISSING_HOLDOUT_OR_COST_EVIDENCE");
  return {json:{status:reasons.length?"FAIL":"ELIGIBLE_FOR_PAPER_REVIEW",realizedPayoff,reasons,
    metrics,limits,livePromotionAllowed:false},pairedItem:{item:index}};
});
